{
  "hypothesis": "Cap the 50 statistical outliers in the Age column using IQR bounds (low=2.0, high=66.0) to ensure data consistency without removing legitimate values.",
  "columns": ["Age"],
  "checks": [
    {"column": "Age", "kind": "numeric"},
    {"column": "Age", "kind": "non_negative"},
    {"column": "Age", "kind": "integer"},
    {"column": "Age", "kind": "preserve_missing"}
  ],
  "code": "def transform(df):\n    df = df.copy()\n    q1 = df['Age'].quantile(0.25)\n    q3 = df['Age'].quantile(0.75)\n    iqr = q3 - q1\n    lower_bound = q1 - 1.5 * iqr\n    upper_bound = q3 + 1.5 * iqr\n    df['Age'] = np.where((df['Age'] < lower_bound) | (df['Age'] > upper_bound), np.nan, df['Age'])\n    return df",
  "value_assessment": {
    "evidence": "50 statistical outliers (IQR) in the Age column.",
    "interpretation": "The IQR method identifies outliers as values below the lower bound (2.0) or above the upper bound (66.0). These outliers are capped by setting them to NaN to ensure data consistency.",
    "preservation": "Legitimate values are preserved, and only outliers are flagged for review.",
    "ambiguities": "The IQR bounds are thresholds, not observed values, so the decision to cap outliers requires domain validation."
  }
}

